// Semver regex pattern: MAJOR.MINOR.PATCH where each is a non-negative integer
const SEMVER_REGEX = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/

interface RegistryFile {
  path: string
  type: string
  target?: string
}

interface RegistryMeta {
