/**
 * Utility functions for version comparison.
 * These can be used in pre-commit hooks or CI to verify version bumps.
 */
export function parseVersion(version: string): {
  major: number
  minor: number
  patch: number
} | null {
  const match = version.match(SEMVER_REGEX)
  if (!match) return null

  return {
    major: parseInt(match[1], 10),
    minor: parseInt(match[2], 10),
    patch: parseInt(match[3], 10),
  }
}

export function compareVersions(
  v1: string,
  v2: string
): -1 | 0 | 1 | null {
  const parsed1 = parseVersion(v1)
  const parsed2 = parseVersion(v2)

  if (!parsed1 || !parsed2) return null

  if (parsed1.major !== parsed2.major) {
    return parsed1.major > parsed2.major ? 1 : -1
  }
  if (parsed1.minor !== parsed2.minor) {
    return parsed1.minor > parsed2.minor ? 1 : -1
  }
  if (parsed1.patch !== parsed2.patch) {
    return parsed1.patch > parsed2.patch ? 1 : -1
  }
  return 0
}

export function isVersionBumped(oldVersion: string, newVersion: string): boolean {
  const comparison = compareVersions(newVersion, oldVersion)
  return comparison === 1
}

describe('Version comparison utilities', () => {
  it('parseVersion should correctly parse valid versions', () => {
    expect(parseVersion('1.2.3')).toEqual({ major: 1, minor: 2, patch: 3 })
    expect(parseVersion('0.0.0')).toEqual({ major: 0, minor: 0, patch: 0 })
    expect(parseVersion('10.20.30')).toEqual({ major: 10, minor: 20, patch: 30 })
  })

  it('parseVersion should return null for invalid versions', () => {
    expect(parseVersion('invalid')).toBeNull()
    expect(parseVersion('1.0')).toBeNull()
    expect(parseVersion('')).toBeNull()
  })

  it('compareVersions should correctly compare versions', () => {
    expect(compareVersions('1.0.0', '1.0.0')).toBe(0)
    expect(compareVersions('2.0.0', '1.0.0')).toBe(1)
    expect(compareVersions('1.0.0', '2.0.0')).toBe(-1)
    expect(compareVersions('1.1.0', '1.0.0')).toBe(1)
    expect(compareVersions('1.0.1', '1.0.0')).toBe(1)
    expect(compareVersions('1.0.0', '1.1.0')).toBe(-1)
    expect(compareVersions('1.0.0', '1.0.1')).toBe(-1)
  })

  it('isVersionBumped should detect version increases', () => {
    expect(isVersionBumped('1.0.0', '1.0.1')).toBe(true)
    expect(isVersionBumped('1.0.0', '1.1.0')).toBe(true)
    expect(isVersionBumped('1.0.0', '2.0.0')).toBe(true)
    expect(isVersionBumped('1.0.0', '1.0.0')).toBe(false)
    expect(isVersionBumped('2.0.0', '1.0.0')).toBe(false)
  })
})

/**
 * Shared Types Coverage Test
 *
 * Validates that every named import from './types' or '../types' in registry
 * files actually exists as an export in registry/shared-types.ts.
 *
 * This prevents the scenario where a component imports a type that exists in
 * a local types.ts file but is missing from the shared types file that gets
 * installed as components/ui/types.ts via the manifest-types registry item.
 */

import { readFileSync, readdirSync, statSync } from 'fs'
import { join, resolve, relative } from 'path'
import { describe, it, expect } from 'vitest'

const ROOT_PATH = resolve(__dirname, '..')
const REGISTRY_PATH = resolve(ROOT_PATH, 'registry')
const SHARED_TYPES_PATH = resolve(REGISTRY_PATH, 'shared-types.ts')

/**
 * Get all exported names from shared-types.ts
 */
function getSharedTypeExports(): Set<string> {
  const content = readFileSync(SHARED_TYPES_PATH, 'utf-8')
  const exports = new Set<string>()

  // Match: export interface Name
  // Match: export type Name
  // Match: export enum Name
  // Match: export const Name
  // Match: export function Name
  const exportRegex = /^export\s+(?:interface|type|enum|const|function)\s+(\w+)/gm
  let match: RegExpExecArray | null
  while ((match = exportRegex.exec(content)) !== null) {
    exports.add(match[1])
  }

  return exports
}

/**
 * Extract named imports from types paths in a file
 */
function extractTypesImports(
  filePath: string
): { names: string[]; line: number; importPath: string }[] {
  const content = readFileSync(filePath, 'utf-8')
  const lines = content.split('\n')
  const results: { names: string[]; line: number; importPath: string }[] = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    // Match imports from ./types or ../types (with optional type keyword)
    const match = line.match(
      /import\s+(?:type\s+)?\{([^}]+)\}\s+from\s+['"](\.\.\?\/types|\.\/types)['"]/
    )
    if (!match) continue

    const namesStr = match[1]
    const importPath = match[2]
    const names = namesStr
      .split(',')
      .map((n) => n.trim())
      .filter((n) => n.length > 0)
      // Handle `type X` inside import { type X, Y }
      .map((n) => n.replace(/^type\s+/, ''))

    results.push({ names, line: i + 1, importPath })
  }

  return results
}

/**
 * Get all .ts/.tsx files recursively in a directory
 */
function getAllFiles(dir: string): string[] {
  const files: string[] = []
  const entries = readdirSync(dir)

  for (const entry of entries) {
    const fullPath = join(dir, entry)
    const stat = statSync(fullPath)

    if (stat.isDirectory()) {
      files.push(...getAllFiles(fullPath))
    } else if (entry.endsWith('.ts') || entry.endsWith('.tsx')) {
      files.push(fullPath)
    }
  }

  return files
}

describe('Shared Types Coverage', () => {
  const sharedExports = getSharedTypeExports()
  const allFiles = getAllFiles(REGISTRY_PATH).filter(
    (f) => !f.endsWith('shared-types.ts')
  )

  it('should have exports in shared-types.ts', () => {
    expect(sharedExports.size).toBeGreaterThan(0)
  })

  for (const absPath of allFiles) {
    const relPath = relative(ROOT_PATH, absPath)
    const imports = extractTypesImports(absPath)

    if (imports.length === 0) continue

    it(`${relPath} — all types imports exist in shared-types.ts`, () => {
      const errors: string[] = []

      for (const imp of imports) {
        for (const name of imp.names) {
          if (!sharedExports.has(name)) {
            errors.push(
              `"${name}" is imported from '${imp.importPath}' at line ${imp.line} but is not exported from shared-types.ts`
            )
          }
        }
      }

      if (errors.length > 0) {
        throw new Error(
          `File "${relPath}" imports types not found in shared-types.ts:\n\n` +
            errors.map((e) => `  ${e}`).join('\n') +
            '\n\n' +
            'When a component is installed via shadcn CLI, imports from ./types or ../types\n' +
            'resolve to components/ui/types.ts (shared-types.ts). Every named import must\n' +
            'be exported from registry/shared-types.ts.'
        )
      }

      expect(errors).toHaveLength(0)
    })
  }
})

/**
 * No Next.js Imports Test
 *
 * This test ensures that registry components do not use any Next.js-specific imports.
 * The component library should be pure React to allow usage in any React environment,
 * not just Next.js applications.
 *
 * Forbidden imports include:
 * - next/dynamic
 * - next/image
 * - next/link
 * - next/router
 * - next/navigation
 * - Any other 'next/*' import
 */

import { readFileSync, readdirSync, statSync } from 'fs'
import { join, resolve } from 'path'
import { describe, it, expect } from 'vitest'

const REGISTRY_PATH = resolve(__dirname, '..', 'registry')

/**
 * Recursively get all .tsx files in a directory
 */
function getAllTsxFiles(dir: string): string[] {
  const files: string[] = []
  const entries = readdirSync(dir)

  for (const entry of entries) {
    const fullPath = join(dir, entry)
    const stat = statSync(fullPath)

    if (stat.isDirectory()) {
      files.push(...getAllTsxFiles(fullPath))
    } else if (entry.endsWith('.tsx') || entry.endsWith('.ts')) {
      files.push(fullPath)
    }
  }

  return files
}

/**
 * Check if a file contains Next.js imports
 */
function findNextJsImports(filePath: string): string[] {
  const content = readFileSync(filePath, 'utf-8')
  const lines = content.split('\n')
  const nextImports: string[] = []

  // Patterns to detect Next.js imports
  const nextImportPatterns = [
    /from\s+['"]next\//,
    /import\s+.*\s+from\s+['"]next\//,
    /require\s*\(\s*['"]next\//,
    /import\s*\(\s*['"]next\//,
  ]

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    for (const pattern of nextImportPatterns) {
      if (pattern.test(line)) {
        nextImports.push(`Line ${i + 1}: ${line.trim()}`)
        break
      }
    }
  }

  return nextImports
}

describe('No Next.js Imports in Registry Components', () => {
  const tsxFiles = getAllTsxFiles(REGISTRY_PATH)

  it('should find registry component files', () => {
    expect(tsxFiles.length).toBeGreaterThan(0)
  })

  describe('Component files must not import from next/*', () => {
    for (const filePath of tsxFiles) {
      const relativePath = filePath.replace(REGISTRY_PATH, 'registry')

      it(`${relativePath} should not have Next.js imports`, () => {
        const nextImports = findNextJsImports(filePath)

        if (nextImports.length > 0) {
          throw new Error(
            `File "${relativePath}" contains Next.js imports!\n\n` +
              `Found imports:\n${nextImports.map((i) => `  ${i}`).join('\n')}\n\n` +
              `Registry components must be pure React without Next.js dependencies.\n` +
              `This ensures the components can be used in any React environment.\n\n` +
              `Common replacements:\n` +
              `  - next/dynamic → React.lazy() with Suspense, or useEffect-based lazy loading\n` +
              `  - next/image → standard <img> tag\n` +
              `  - next/link → standard <a> tag or react-router Link\n` +
              `  - next/router → window.location or react-router hooks`
          )
        }

        expect(nextImports).toHaveLength(0)
      })
    }
  })

  it('should provide a summary of any Next.js imports found', () => {
    const filesWithNextImports: { file: string; imports: string[] }[] = []

    for (const filePath of tsxFiles) {
      const nextImports = findNextJsImports(filePath)
      if (nextImports.length > 0) {
        filesWithNextImports.push({
          file: filePath.replace(REGISTRY_PATH, 'registry'),
          imports: nextImports,
        })
      }
    }

    if (filesWithNextImports.length > 0) {
      console.log('\n=== Files with Next.js Imports ===')
      for (const { file, imports } of filesWithNextImports) {
        console.log(`\n${file}:`)
        for (const imp of imports) {
          console.log(`  ${imp}`)
        }
      }
    }

    expect(filesWithNextImports).toHaveLength(0)
  })
})

/**
 * Component Demo Data Initialization Test
 *
 * Ensures every registered block with a `data?` prop uses the `resolved`
 * initialization pattern:
 *   const resolved: NonNullable<Props['data']> = data ?? demoData
 *
 * This guarantees components render meaningful content when called without
 * arguments (e.g. `<Component />`), which is required for MCP Jam previews
 * and zero-config usage.
 *
 * Components without a `data?` prop (e.g. utility libs, types-only files)
 * are excluded automatically.
 */

import { readFileSync } from 'fs'
import { resolve, relative } from 'path'
import { describe, it, expect } from 'vitest'

const ROOT_PATH = resolve(__dirname, '..')

interface RegistryFile {
  path: string
  type: string
  target: string
}

interface RegistryItem {
  name: string
  type: string
  files: RegistryFile[]
}

/**
 * Read registry.json and return only `registry:block` items
 * (excluding libs, types, and shared utilities).
 */
function getRegisteredBlocks(): RegistryItem[] {
  const registryJson = JSON.parse(
    readFileSync(resolve(ROOT_PATH, 'registry.json'), 'utf-8')
  )
  return registryJson.items.filter(
    (item: RegistryItem) => item.type === 'registry:block'
  )
}

/**
 * Find the main .tsx block file for a registry item.
 * The main file is the first `registry:block` typed file.
 */
function getMainBlockFile(item: RegistryItem): string | null {
  const blockFile = item.files.find((f) => f.type === 'registry:block')
  return blockFile ? blockFile.path : null
}

/**
 * Check if a component file has a `data?` prop in its Props interface.
 */
function hasDataProp(content: string): boolean {
  // Match interfaces with data?: { ... } pattern
  return /interface\s+\w+Props\s*\{[^}]*\bdata\?:/s.test(content)
}

/**
 * Extract the category from a registry file path.
 * e.g. "registry/form/contact-form.tsx" -> "form"
 */
function getCategoryFromPath(filePath: string): string | null {
  const match = filePath.match(/^registry\/([^/]+)\//)
  return match ? match[1] : null
}

describe('Component Demo Data Initialization', () => {
  const blocks = getRegisteredBlocks()

  it('should find registered blocks to check', () => {
    expect(blocks.length).toBeGreaterThan(0)
  })

  for (const block of blocks) {
    const mainFile = getMainBlockFile(block)
    if (!mainFile) continue

    const absPath = resolve(ROOT_PATH, mainFile)
    let content: string
    try {
      content = readFileSync(absPath, 'utf-8')
    } catch {
      continue
    }

    // Skip components without a data? prop
    if (!hasDataProp(content)) continue

    const category = getCategoryFromPath(mainFile)
    const relPath = relative(ROOT_PATH, absPath)

    describe(`${block.name} (${relPath})`, () => {
      it('must import demo data from ./demo/<category>', () => {
        const importPattern = new RegExp(
          `from\\s+['"]\\./demo/${category}['"]`
        )
        expect(content).toMatch(importPattern)
      })

      it('must use data ?? demo fallback pattern', () => {
        // Match: data ?? demo<Something> or data ?? { ... demo<Something> }
        const fallbackPattern = /=\s*data\s*\?\?\s*(?:demo\w+|\{[^}]*demo\w+)/
        expect(content).toMatch(fallbackPattern)
      })
    })
  }
})
